import{_ as e,c as a,o as u,a4 as t}from"./chunks/framework.mdxl8zx-.js";const p=JSON.parse('{"title":"常见面试题","description":"","frontmatter":{},"headers":[],"relativePath":"frontEnd/vue/常见面试题.md","filePath":"frontEnd/vue/常见面试题.md"}'),s={name:"frontEnd/vue/常见面试题.md"},r=t('<h1 id="常见面试题" tabindex="-1">常见面试题 <a class="header-anchor" href="#常见面试题" aria-label="Permalink to &quot;常见面试题&quot;">​</a></h1><h2 id="_1、什么是vue-js-它有哪些优点" tabindex="-1">1、什么是Vue.js？它有哪些优点？ <a class="header-anchor" href="#_1、什么是vue-js-它有哪些优点" aria-label="Permalink to &quot;1、什么是Vue.js？它有哪些优点？&quot;">​</a></h2><p>Vue是一个渐进式的JavaScript框架，用户构建用户界面，简单易学、性能高、文档丰富、生态系统完备、灵活性高、可复用性强</p><h2 id="_2、vue-js的生命周期有哪些-请简述每个生命周期的作用" tabindex="-1">2、Vue.js的生命周期有哪些？请简述每个生命周期的作用 <a class="header-anchor" href="#_2、vue-js的生命周期有哪些-请简述每个生命周期的作用" aria-label="Permalink to &quot;2、Vue.js的生命周期有哪些？请简述每个生命周期的作用&quot;">​</a></h2><p>Vue2：beforeCreate和created是组件化实例前和实例后的钩子函数；beforeMount和mounted是组件挂载前后挂载后的钩子函数；beforeUpdate和updated是组件更新前和更新后的钩子函数；beforeDestory和destoryed是组件销毁前和销毁后的钩子函数。</p><p>Vue3：created生命周期换成setup，语法变成onBeforeXXX和onXXX</p><h2 id="_3、请简述vue-js的双向数据绑定原理" tabindex="-1">3、请简述Vue.js的双向数据绑定原理 <a class="header-anchor" href="#_3、请简述vue-js的双向数据绑定原理" aria-label="Permalink to &quot;3、请简述Vue.js的双向数据绑定原理&quot;">​</a></h2><p>Vuejs的数据双向绑定原理是通过数据劫持和发布订阅模式来实现的。当数据改变时，Vuejs会自动更新视图，而当视图改变时也会自动更新数据</p><h2 id="_4、vue-js中指令和组件有什么区别" tabindex="-1">4、Vue.js中指令和组件有什么区别？ <a class="header-anchor" href="#_4、vue-js中指令和组件有什么区别" aria-label="Permalink to &quot;4、Vue.js中指令和组件有什么区别？&quot;">​</a></h2><p>指令是Vuejs中用于操作DOM元素的的特殊属性，常用的指令有v-model、v-bind、v-for、v-if等，而组件是Vuejs中用于封装可复用UI组件的方式，可以通过注册组件进行复用</p><h2 id="_5、vue-js中的数据响应式是如何实现的" tabindex="-1">5、Vue.js中的数据响应式是如何实现的？ <a class="header-anchor" href="#_5、vue-js中的数据响应式是如何实现的" aria-label="Permalink to &quot;5、Vue.js中的数据响应式是如何实现的？&quot;">​</a></h2><p>Vue2中是通过Object.defineproperty()方法实现的，Vue3是通过Proxy和Reflect来实现的。当数据发生变化是，自动的更新依赖</p><h2 id="_6、vue-js中的computed和watch有什么区别" tabindex="-1">6、Vue.js中的computed和watch有什么区别？ <a class="header-anchor" href="#_6、vue-js中的computed和watch有什么区别" aria-label="Permalink to &quot;6、Vue.js中的computed和watch有什么区别？&quot;">​</a></h2><p>computed是用于计算属性的特殊方法，他会依赖自动缓存结果；而watch是用来监听数据变化而执行相关的自定义操作的，可以监听到每次数据的变化</p><h2 id="_7、vue-js中的路由是什么-请简述vue-js中的路由实现原理" tabindex="-1">7、Vue.js中的路由是什么？请简述Vue.js中的路由实现原理 <a class="header-anchor" href="#_7、vue-js中的路由是什么-请简述vue-js中的路由实现原理" aria-label="Permalink to &quot;7、Vue.js中的路由是什么？请简述Vue.js中的路由实现原理&quot;">​</a></h2><p>路由是用于控制页面跳转的机制，Vuejs中通过vue-router实现，其原理是通过监听URL变化，根据不同的URL展示不同的组件</p><h2 id="_8、vue-js中的vuex是什么-请简述vuex的作用和使用场景" tabindex="-1">8、Vue.js中的vuex是什么？请简述vuex的作用和使用场景 <a class="header-anchor" href="#_8、vue-js中的vuex是什么-请简述vuex的作用和使用场景" aria-label="Permalink to &quot;8、Vue.js中的vuex是什么？请简述vuex的作用和使用场景&quot;">​</a></h2><p>Vuex是一个状态管理工具，用来管理全局数据和状态。包括：集中管理共享状态、规范化状态变化、方便调试和测试、提高代码的复用率。使用场景包括：多个组件需要共享同一状态、同一状态需要在多个视图中展示、需要对状态进行统一的管理和调试</p><h2 id="_9、vue-js中如何实现异步组件加载" tabindex="-1">9、Vue.js中如何实现异步组件加载？ <a class="header-anchor" href="#_9、vue-js中如何实现异步组件加载" aria-label="Permalink to &quot;9、Vue.js中如何实现异步组件加载？&quot;">​</a></h2><p>异步组件加载可以通过Vuejs的动态导入来实现的。可以使用动态的import语法来实现</p><h2 id="_10、vue-js中的mixins有什么作用-请举例说明" tabindex="-1">10、Vue.js中的mixins有什么作用？请举例说明 <a class="header-anchor" href="#_10、vue-js中的mixins有什么作用-请举例说明" aria-label="Permalink to &quot;10、Vue.js中的mixins有什么作用？请举例说明&quot;">​</a></h2><p>mixins是Vuejs中用于多组件间复用代码的方式，它可以将多个组件的公共代码提取出来，形成一个混入对象，然后将其注入到多个组件中，从而实现代码复用</p>',22),o=[r];function i(n,h,d,c,l,j){return u(),a("div",null,o)}const v=e(s,[["render",i]]);export{p as __pageData,v as default};
